import java.util.Scanner;

public class Main {
    static final int N = 105;
    static final long INF = 1000000000000000L;
    static long[][] mt = new long[N][N];

    static int n;
    static int[] a = new int[N];
    static long T;
    static long[][] d = new long[N][N];
    static long[][] dt = new long[N][N];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        T = scanner.nextLong();
        for (int i = 0; i < n; ++i) {
            a[i] = scanner.nextInt();
        }
        for (int s = 0; s < n; ++s) {
            for (int i = 0; i < n; ++i) {
                if (a[i] < a[s]) {
                    d[s][i] = -INF;
                } else {
                    d[s][i] = 1;
                    for (int j = 0; j < i; ++j) {
                        if (a[j] <= a[i]) {
                            d[s][i] = Math.max(d[s][i], d[s][j] + 1);
                        }
                    }
                }
            }
        }
        binpow(d, T, dt);
        long res = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                res = Math.max(res, dt[i][j]);
            }
        }
        System.out.println(res);
    }

    static void one(long[][] a) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                a[i][j] = 0;
            }
        }
    }

    static void copy(long[][] a, long[][] b) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                b[i][j] = a[i][j];
            }
        }
    }

    static void mul(long[][] a, long[][] b, long[][] c) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                c[i][j] = -INF;
                for (int k = 0; k < n; ++k) {
                    c[i][j] = Math.max(c[i][j], a[i][k] + b[k][j]);
                }
            }
        }
    }

    static long[][] t = new long[N][N];
    static long[][] r = new long[N][N];

    static void binpow(long[][] a, long b, long[][] c) {
        copy(a, t);
        one(c);
        while (b != 0) {
            if ((b & 1) != 0) {
                mul(c, t, r);
                copy(r, c);
            }
            mul(t, t, r);
            copy(r, t);
            b >>= 1;
        }
    }
}

import java.util.Scanner;

public class Main {
    static final int N = 100 + 5;
    static final long INF = 1000000000000000L;
    static int n;
    static int[] a = new int[N];
    static long T;
    static long[][] d = new long[N][N];
    static long[][] dt = new long[N][N];
    static long[][] t = new long[N][N];
    static long[][] r = new long[N][N];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        T = sc.nextLong();
        for (int i = 0; i < n; ++i) {
            a[i] = sc.nextInt();
        }

        for (int s = 0; s < n; ++s) {
            for (int i = 0; i < n; ++i) {
                if (a[i] < a[s]) {
                    d[s][i] = -INF;
                } else {
                    d[s][i] = 1;
                    for (int j = 0; j < i; ++j) {
                        if (a[j] <= a[i]) {
                            d[s][i] = Math.max(d[s][i], d[s][j] + 1);
                        }
                    }
                }
            }
        }

        binpow(d, T, dt);

        long res = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                res = Math.max(res, dt[i][j]);
            }
        }
        System.out.println(res);
    }

    static void one(long[][] a) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                a[i][j] = 0;
            }
        }
    }

    static void copy(long[][] a, long[][] b) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                b[i][j] = a[i][j];
            }
        }
    }

    static void mul(long[][] a, long[][] b, long[][] c) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                c[i][j] = -INF;
                for (int k = 0; k < n; ++k) {
                    c[i][j] = Math.max(c[i][j], a[i][k] + b[k][j]);
                }
            }
        }
    }

    static void binpow(long[][] a, long b, long[][] c) {
        copy(a, t);
        one(c);
        while (b != 0) {
            if ((b & 1) != 0) {
                mul(c, t, r);
                copy(r, c);
            }
            mul(t, t, r);
            copy(r, t);
            b >>= 1;
        }
    }
}

