using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace lab11
{
    using li = System.Int64;
    using mt = System.Int64;
    class Program
    {
        const int N = 100 + 5;
        public static li INF = 1000000000000000;
        static li[,] mt = new li[N, N];

        static int n;
        static int[] a = new int[N];
        static li T;
        static mt[,] d = new mt[N,N];
        static mt[,] dt = new mt[N,N];

        static void Main(string[] args)
        {
            int[] input = Console.ReadLine().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Select(p => int.Parse(p)).ToArray<int>();
            n = input[0];
            T = input[1];
            input = Console.ReadLine().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Select(p => int.Parse(p)).ToArray<int>();
            for (int i = 0; i < n; ++i)
                a[i] = input[i];
            for (int s = 0; s < n; ++s)
            {
                for (int i = 0; i < n; ++i)
                {
                    if (a[i] < a[s])
                    {
                        d[s, i] = -INF;
                    }
                    else
                    {
                        d[s, i] = 1;
                        for (int j = 0; j < i; ++j)
                            if (a[j] <= a[i])
                                d[s, i] = Math.Max(d[s, i], d[s, j] + 1);
                    }
                }
            }
            binpow(d, T, dt);
            li res = 0;
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    res = Math.Max(res, dt[i, j]);
            Console.WriteLine(res);
        }

        static void one(mt[,] a) 
        {
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    a[i,j] = 0;
        }

        static void copy(mt[,] a, mt[,] b) 
        {
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    b[i, j] = a[i, j];
        }

        static void mul(mt[,] a, mt[,] b, mt[,] c) 
        {
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j) {
                    c[i,j] = -INF;
                    for (int k = 0; k < n; ++k)
                        c[i,j] = Math.Max(c[i,j], a[i,k] + b[k,j]);
                }
        }

        static mt[,] t = new mt[N, N];
        static mt[,] r = new mt[N, N];

        static void binpow(mt[,] a, li b, mt[,] c) 
        {
            copy(a, t);
            one(c);
            while (b != 0) {
                if ((b & 1) != 0) {
                    mul(c, t, r);
                    copy(r, c);
                }
                mul(t, t, r);
                copy(r, t);
                b >>= 1;
            }
        }         
    }
}
